process DIAMOND_BLASTX {
    tag "${meta.id}"
    label 'process_high'

    conda "${moduleDir}/environment.yml"
    container "${workflow.containerEngine in ['singularity', 'apptainer'] && !task.ext.singularity_pull_docker_container
        ? 'https://depot.galaxyproject.org/singularity/diamond:2.2.1--he361c42_0'
        : 'quay.io/biocontainers/diamond:2.2.1--he361c42_0'}"

    input:
    tuple val(meta), path(fasta)
    tuple val(meta2), path(db)
    val out_ext
    val blast_columns

    output:
    tuple val(meta), path('*.blast'), optional: true, emit: blast
    tuple val(meta), path('*.xml'), optional: true, emit: xml
    tuple val(meta), path('*.txt'), optional: true, emit: txt
    tuple val(meta), path('*.daa'), optional: true, emit: daa
    tuple val(meta), path('*.sam'), optional: true, emit: sam
    tuple val(meta), path('*.tsv'), optional: true, emit: tsv
    tuple val(meta), path('*.paf'), optional: true, emit: paf
    tuple val(meta), path("*.log"), emit: log
    tuple val("${task.process}"), val('diamond'), eval("diamond --version | sed 's/diamond version //g'"), emit: versions_diamond, topic: versions

    when:
    task.ext.when == null || task.ext.when

    script:
    def args = task.ext.args ?: ''
    def prefix = task.ext.prefix ?: "${meta.id}"
    def is_compressed = fasta.getExtension() == "gz" ? true : false
    def fasta_name = is_compressed ? fasta.getBaseName() : fasta
    def columns = blast_columns ? "${blast_columns}" : ''
    if (out_ext == 'blast') {
        outfmt = 0
    }
    else if (out_ext == 'xml') {
        outfmt = 5
    }
    else if (out_ext == 'txt') {
        outfmt = 6
    }
    else if (out_ext == 'daa') {
        outfmt = 100
    }
    else if (out_ext == 'sam') {
        outfmt = 101
    }
    else if (out_ext == 'tsv') {
        outfmt = 102
    }
    else if (out_ext == 'paf') {
        outfmt = 103
    }
    else {
        outfmt = 6
        out_ext = 'txt'
        log.warn("Unknown output file format provided (${out_ext}): selecting DIAMOND default of tabular BLAST output (txt)")
    }
    """
    if [ "${is_compressed}" == "true" ]; then
        gzip -c -d ${fasta} > ${fasta_name}
    fi

    DB=`find -L ./ -name "*.dmnd" | sed 's/\\.dmnd\$//'`

    diamond \\
        blastx \\
        --threads ${task.cpus} \\
        --db \$DB \\
        --query ${fasta_name} \\
        --outfmt ${outfmt} ${columns} \\
        ${args} \\
        --out ${prefix}.${out_ext} \\
        --log

    mv diamond.log ${prefix}.log
    """

    stub:
    def args = task.ext.args ?: ''
    def prefix = task.ext.prefix ?: "${meta.id}"
    if (out_ext == 'blast') {
        outfmt = 0
    }
    else if (out_ext == 'xml') {
        outfmt = 5
    }
    else if (out_ext == 'txt') {
        outfmt = 6
    }
    else if (out_ext == 'daa') {
        outfmt = 100
    }
    else if (out_ext == 'sam') {
        outfmt = 101
    }
    else if (out_ext == 'tsv') {
        outfmt = 102
    }
    else if (out_ext == 'paf') {
        outfmt = 103
    }
    else {
        outfmt = 6
        out_ext = 'txt'
        log.warn("Unknown output file format provided (${out_ext}): selecting DIAMOND default of tabular BLAST output (txt)")
    }

    """
    echo "${args}"
    touch ${prefix}.${out_ext}
    touch ${prefix}.log
    """
}

nextflow_process {

    name "Test Process DIAMOND_BLASTX"
    script "../main.nf"
    process "DIAMOND_BLASTX"
    tag "modules"
    tag "modules_nfcore"
    tag "diamond"
    tag "diamond/makedb"
    tag "diamond/blastx"

    setup {
        run("DIAMOND_MAKEDB") {
            script "../../makedb/main.nf"
            process {
                """
                input[0] = [ [id:'test2'], [ file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta', checkIfExists: true) ] ]
                input[1] = []
                input[2] = []
                input[3] = []
                """
            }
        }
    }

    test("Should search for transcriptome hits against a DIAMOND db and return the default tab separated output file of hits") {

        when {
            params {
                outdir = "$outputDir"
            }
            process {
                """
                input[0] = [ [id:'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/transcriptome.fasta', checkIfExists: true) ]
                input[1] = DIAMOND_MAKEDB.out.db
                input[2] = 'tfdfdt' // Nonsense file extension to check default case.
                input[3] = 'qseqid qlen'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path(process.out.log.get(0).get(1)).readLines().contains("11 queries aligned.") },
                { assert snapshot(
                    process.out.txt,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                    ).match()
                }
            )
        }

    }

    test("Should search for transcriptome hits against a DIAMOND db and return the daa format output file of hits") {

        when {
            params {
                outdir = "$outputDir"
            }
            process {
                """
                input[0] = [ [id:'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/transcriptome.fasta', checkIfExists: true) ]
                input[1] = DIAMOND_MAKEDB.out.db
                input[2] = 'daa'
                input[3] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.daa },
                { assert path(process.out.log.get(0).get(1)).readLines().contains("11 queries aligned.") },
                { assert snapshot(process.out.findAll { key, val -> key.startsWith('versions') }).match() }
            )
        }

    }
}

